// Page « Mes disponibilités » du Coach (UKAN V2)
// Interface de gestion des disponibilités hebdomadaires + exceptions de dates.
// Données conservées en mémoire de session (mode démo, comme le reste de l'app).
// Ouverte depuis : Avancé → Passer en mode Coach → Dashboard Coach → Mes Dispos.
// ignore_for_file: annotate_overrides, curly_braces_in_flow_control_structures, deprecated_member_use

import 'package:flutter/material.dart';
import 'appointment_models.dart';
import 'appointments_repository.dart';

const cream=Color(0xfff8f6f1), ink=Color(0xff252321), muted=Color(0xff8d8a86), gold=Color(0xffeda900), green=Color(0xff176b50), red=Color(0xffff555d);

class CoachAvailabilityPage extends StatefulWidget {
  final String coachId;
  const CoachAvailabilityPage({super.key, this.coachId = 'coach_1'});
  State<CoachAvailabilityPage> createState()=>_CoachAvailabilityPageState();
}

class _CoachAvailabilityPageState extends State<CoachAvailabilityPage> with SingleTickerProviderStateMixin {
  late final TabController tabs;
  final _repo=AppointmentsRepository();
  late List<DayAvailability> days;
  late List<AvailabilityException> exceptions;
  final expanded=<String>{'2026-08','2026-09'};
  void initState(){super.initState();tabs=TabController(length:2,vsync:this);days=_repo.getOrCreateWeekly(widget.coachId).map((d)=>d.copy()).toList();exceptions=_repo.getAvailabilityExceptions(widget.coachId).map((e)=>e.copy()).toList();}
  void dispose(){tabs.dispose();super.dispose();}
  void _persistWeek()=>_repo.setWeeklyAvailability(widget.coachId,days);
  void _persistExceptions()=>_repo.setAvailabilityExceptions(widget.coachId,exceptions);
  void msg(String s){ScaffoldMessenger.of(context)..hideCurrentSnackBar()..showSnackBar(SnackBar(content:Text(s),behavior:SnackBarBehavior.floating));}

  Future<void> editDay(int i) async {
    final r=await showModalBottomSheet<DayResult>(context:context,isScrollControlled:true,useSafeArea:true,backgroundColor:cream,shape:const RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(28))),builder:(_)=>DaySheet(day:days[i].copy()));
    if(r==null||!mounted)return;
    setState((){days[i]=r.day;for(final x in r.targets)days[x]=DayAvailability(days[x].name,r.day.ranges.map((e)=>e.copy()).toList(),enabled:r.day.enabled);});_persistWeek();msg('Horaires enregistrés');
  }
  Future<void> editException([AvailabilityException? old]) async {
    final r=await showModalBottomSheet<AvailabilityException>(context:context,isScrollControlled:true,useSafeArea:true,backgroundColor:cream,shape:const RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(28))),builder:(_)=>ExceptionSheet(value:old?.copy()));
    if(r==null||!mounted)return;setState((){if(old==null){r.id=exceptions.fold(0,(m,e)=>e.id>m?e.id:m)+1;exceptions.add(r);}else{r.id=old.id;exceptions[exceptions.indexWhere((e)=>e.id==old.id)]=r;}exceptions.sort((a,b)=>a.start.compareTo(b.start));expanded.add(monthKey(r.start));});_persistExceptions();msg(old==null?'Exception ajoutée':'Exception modifiée');
  }
  Future<void> remove(AvailabilityException e) async {final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Supprimer cette exception ?'),content:const Text('Cette action est définitive pour la session.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(c,true),style:FilledButton.styleFrom(backgroundColor:red),child:const Text('Supprimer'))]));if(ok==true&&mounted){setState(()=>exceptions.remove(e));_persistExceptions();msg('Exception supprimée');}}

  Widget build(BuildContext context)=>Scaffold(backgroundColor:cream,appBar:AppBar(backgroundColor:cream,surfaceTintColor:Colors.transparent,centerTitle:true,title:const Text('Mes disponibilités',style:TextStyle(fontWeight:FontWeight.w800,fontSize:19)),actions:[IconButton(onPressed:()=>msg('Disponibilités conservées pour cette session'),icon:const Icon(Icons.check_circle_outline,color:gold))],bottom:TabBar(controller:tabs,labelColor:ink,unselectedLabelColor:muted,indicatorColor:gold,indicatorWeight:3,tabs:const [Tab(text:'Semaine'),Tab(text:'Exceptions')])),body:SafeArea(top:false,child:TabBarView(controller:tabs,children:[week(),exceptionTab()])));
  Widget week()=>ListView(padding:const EdgeInsets.all(16),children:[const Heading('Votre semaine','Appuyez sur un jour pour le modifier'),const SizedBox(height:12),...List.generate(7,(i)=>Padding(padding:const EdgeInsets.only(bottom:10),child:CardBox(child:InkWell(onTap:()=>editDay(i),child:Padding(padding:const EdgeInsets.all(15),child:Row(children:[Container(width:10,height:10,decoration:BoxDecoration(shape:BoxShape.circle,color:days[i].enabled?green:red)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(days[i].name,style:const TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:5),Text(days[i].summary,style:const TextStyle(color:muted,fontSize:13))])),const Icon(Icons.chevron_right,color:muted)]))))))]);
  Widget exceptionTab(){final map=<String,List<AvailabilityException>>{};for(final e in exceptions)map.putIfAbsent(monthKey(e.start),()=>[]).add(e);return ListView(padding:const EdgeInsets.all(16),children:[Row(children:[const Expanded(child:Heading('Exceptions de dates','Vacances et horaires particuliers')),FilledButton.icon(onPressed:editException,style:FilledButton.styleFrom(backgroundColor:gold,foregroundColor:ink),icon:const Icon(Icons.add),label:const Text('Ajouter'))]),const SizedBox(height:16),if(map.isEmpty)const CardBox(child:Padding(padding:EdgeInsets.all(30),child:Center(child:Text('Aucune exception enregistrée')))) else ...map.entries.map((g){final open=expanded.contains(g.key);return Padding(padding:const EdgeInsets.only(bottom:12),child:CardBox(child:Column(children:[ListTile(leading:const Icon(Icons.calendar_month_outlined,color:green),title:Text('${monthLabel(g.value.first.start)} — ${g.value.length} exception${g.value.length>1?'s':''}',style:const TextStyle(fontWeight:FontWeight.w800)),trailing:Icon(open?Icons.expand_less:Icons.expand_more),onTap:()=>setState(()=>open?expanded.remove(g.key):expanded.add(g.key))),if(open)...g.value.map((e)=>Container(decoration:const BoxDecoration(border:Border(top:BorderSide(color:Color(0xffebe7df)))),child:ListTile(title:Text(e.dateLabel,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${e.kind.label}${e.allDay?' · Journée complète':' · ${e.ranges.map((x)=>x.label).join(' · ')}'}${e.reason.isEmpty?'':'\n${e.reason}'}'),isThreeLine:e.reason.isNotEmpty,trailing:PopupMenuButton<String>(onSelected:(x)=>x=='edit'?editException(e):remove(e),itemBuilder:(_)=>const [PopupMenuItem(value:'edit',child:Text('Modifier')),PopupMenuItem(value:'remove',child:Text('Supprimer'))]))))])));})]);}
}

class DaySheet extends StatefulWidget {const DaySheet({super.key,required this.day});final DayAvailability day;State<DaySheet> createState()=>_DaySheetState();}
class _DaySheetState extends State<DaySheet>{late DayAvailability day;final targets=<int>{};String? error;static const names=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];void initState(){super.initState();day=widget.day;}
