  Widget build(BuildContext context)=>SheetFrame(child:(controller)=>ListView(controller:controller,padding:const EdgeInsets.fromLTRB(18,8,18,28),children:[const Handle(),Row(children:[Expanded(child:Text('Modifier ${day.name.toLowerCase()}',style:const TextStyle(fontSize:21,fontWeight:FontWeight.w800))),IconButton(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.close))]),CardBox(child:SwitchListTile(value:day.enabled,activeColor:green,title:const Text('Disponible',style:TextStyle(fontWeight:FontWeight.w800)),subtitle:const Text('Activez les horaires de cette journée'),onChanged:(v)=>setState((){day.enabled=v;if(v&&day.ranges.isEmpty)day.ranges.add(TimeRange(9,0,17,0));}))),const SizedBox(height:14),if(day.enabled)...[...List.generate(day.ranges.length,(i)=>TimeRow(range:day.ranges[i],start:()=>pick(i,true),end:()=>pick(i,false),remove:()=>setState(()=>day.ranges.removeAt(i)))),TextButton.icon(onPressed:()=>setState(()=>day.ranges.add(TimeRange(9,0,17,0))),icon:const Icon(Icons.add),label:const Text('Ajouter un créneau'))],if(error!=null)Text(error!,style:const TextStyle(color:red,fontWeight:FontWeight.w700)),OutlinedButton.icon(onPressed:copyTo,icon:const Icon(Icons.copy_outlined),label:Text(targets.isEmpty?'Copier vers d’autres jours':'Copie vers ${targets.length} jour(s)')),const SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton(onPressed:()=>Navigator.pop(context),child:const Text('Annuler'))),const SizedBox(width:10),Expanded(child:FilledButton(style:FilledButton.styleFrom(backgroundColor:gold,foregroundColor:ink),onPressed:(){final e=validate();if(e!=null){setState(()=>error=e);return;}Navigator.pop(context,DayResult(day,targets));},child:const Text('Enregistrer')))])]));}

